#!/usr/bin/env bash
# Process oracle -- generated by scripts/harborize_bundle.py.
set -euo pipefail
mkdir -p /logs/agent /logs/artifacts
cp /solution/answer.md /logs/agent/answer.md

python3 - <<'PYEOF'
import json, pathlib, subprocess

WORKDIR = '/workspace/pandas-dev__pandas'
COMMANDS = [
    'grep -H -n -A 90 "def result_index_and_ids" pandas/core/groupby/ops.py',
    'grep -H -n -A 40 "def _ob_index_and_ids" pandas/core/groupby/ops.py',
    'grep -H -n -A 14 "def _unob_index_and_ids" pandas/core/groupby/ops.py',
    'grep -H -n -A 18 "def groups" pandas/core/groupby/ops.py',
    'grep -rn "result_index_and_ids" pandas/',
    "sed -n '590,760p' pandas/core/groupby/ops.py",
    "sed -n '660,700p' pandas/core/groupby/groupby.py",
    "sed -n '195,300p' pandas/core/groupby/generic.py",
    "sed -n '640,670p' pandas/core/arrays/categorical.py",
    "sed -n '755,775p' pandas/core/apply.py",
]

steps = []
for i, cmd in enumerate(COMMANDS, start=1):
    proc = subprocess.run(['bash', '-lc', cmd], cwd=WORKDIR,
                          capture_output=True, text=True)
    steps.append({
        'step_id': i,
        'source': 'agent',
        'message': '',
        'tool_calls': [{'tool_call_id': 'call_%d' % i, 'name': 'bash',
                        'arguments': {'command': cmd}}],
        'observation': {'content': (proc.stdout or '') + (proc.stderr or '')},
    })

answer = pathlib.Path('/solution/answer.md').read_text(encoding='utf-8')
steps.append({'step_id': len(steps) + 1, 'source': 'agent', 'message': answer})
pathlib.Path('/logs/agent/trajectory.json').write_text(
    json.dumps({'steps': steps}, indent=1), encoding='utf-8')
print('[oracle] %d commands executed, trajectory written' % len(COMMANDS))
PYEOF

cat /logs/agent/answer.md
